import {changeValue} from '@github-ui/form-utils'
import {remoteForm} from '@github-ui/remote-form'
import {resetUserAddForm} from './user-add'

remoteForm('.js-remote-submit', async function (form, wants) {
  const dialog = form.closest('#block-user-confirmation-dialog') as HTMLDialogElement
  const response = await wants.json()

  const group = document.querySelector<HTMLElement>('.js-user-block-settings-list')
  const list = group?.querySelector<HTMLElement>('.js-blocked-list')
  const blank = group?.querySelector<HTMLElement>('.js-user-block-blank-slate')

  resetUserAddForm(form, false)
  const input = document.querySelector<HTMLInputElement>('.js-add-blocked-user-field')

  if (input) {
    changeValue(input, '')
  }

  if (dialog && 'open' in dialog) {
    dialog.close()
  }

  // Redirects so we can see the banners for unblock/block actions
  if (response.json.redirect) {
    window.location.href = response.json.redirect
  }

  if (blank) blank.hidden = true
  if (list) list.hidden = false
})
